  "proposal_id": "local-proposal",
  "subject": "Model Context Protocol (MCP) Developer Tool",
  "offer": {
    "idea": "A lightweight, open-source MCP development environment that integrates with popular IDEs and provides real-time context-aware code suggestions and refactorings.",
    "falsifiable_benefit": "Within 3 months, developers using this tool will experience a 20% increase in productivity and a 15% reduction in errors, as evidenced by a comprehensive user feedback survey and code review metrics."
  },
  "requested": {
    "evidence": "A survey of 100 developers using the MCP Developer Tool for 3 months, along with code review metrics and qualitative feedback from the developers."
  }
}

